        </div>
      </motion.div>
    );
  } else {
    // Compact style or minimal card for "Sélections Populaires" and "Les Mieux Notés"
    return (
      <motion.div
        whileHover={{ y: -5, transition: { duration: 0.15 } }}
        onClick={handleCardClick}
        className="bg-white rounded-2xl border border-slate-100 overflow-hidden shadow-xs hover:shadow-md transition-shadow flex flex-col h-full relative cursor-pointer"
        id={`product-card-pop-${product.id}`}
      >
        {/* Large backplane pricing as watermark effect if requested, or clean product aspect ratio */}
        <div className="aspect-[4/3] bg-slate-50 overflow-hidden relative group">
          {product.images[0] ? <img
            src={product.images[0]}
            alt={product.titre}
            referrerPolicy="no-referrer"
            className="w-full h-full object-cover group-hover:scale-103 transition-transform duration-300"
          /> : <div className="w-full h-full flex items-center justify-center text-slate-300"><ImageIcon className="w-7 h-7" /></div>}
          {/* Subtle watermark in image to hint at original design feel but kept extremely readable */}
          <div 
            className="absolute bottom-2 left-2 bg-black/40 hover:bg-black/65 backdrop-blur-xs px-2 py-0.5 rounded text-[10px] text-white font-semibold z-10"
            onClick={(e) => {
              e.stopPropagation();
              navigate(`/seller/${encodeURIComponent(product.boutique_id || product.nom_boutique)}`);
            }}
          >
            {product.nom_boutique}
          </div>
        </div>

        {/* Body */}
        <div className="p-3.5 flex flex-col flex-grow justify-between gap-2 bg-slate-50/40">
          <div>
            {/* Category */}
            <p className="text-[10px] font-semibold text-brand tracking-widest uppercase mb-0.5">
              {product.categorie_id}
            </p>
            {/* Title */}
            <h4 className="text-slate-800 font-display font-semibold text-xs sm:text-sm leading-tight line-clamp-1">
              {product.titre}
            </h4>
          </div>

          {/* Price with interaction icons directly aligned inline */}
          <div className="flex items-center justify-between border-t border-slate-100 pt-2.5">
            <span className="text-xs sm:text-sm font-bold text-slate-900 font-mono">
              {formatPrice(product.prix)}
            </span>
            <div className="flex items-center gap-1 text-slate-400">
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  onCallSeller(product);
                }}
                className="p-1 px-1.5 text-slate-600 hover:text-brand hover:bg-brand-light rounded transition-all cursor-pointer"
                title="Consulter le numéro"
                aria-label="Appeler le vendeur"
              >
                <Phone className="w-3.5 h-3.5" />
              </button>
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  onChatSeller(product);
                }}
                className="p-1 px-1.5 text-slate-600 hover:text-brand hover:bg-brand-light rounded transition-all cursor-pointer"
                title="Ouvrir le chat interactif"
                aria-label="Discuter avec le vendeur"
              >
                <MessageSquare className="w-3.5 h-3.5" />
              </button>
            </div>
          </div>
        </div>
      </motion.div>
    );
  }
}

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { supabase } from '../lib/supabase';
import { User } from '@supabase/supabase-js';
import { resolveProfileRole } from '../lib/mappers';

// Define the User Profile structure matching our Supabase public.utilisateurs table
export interface UserProfile {
  id: string;
  nom: string;
  email: string;
  telephone?: string;
  role: 'Acheteur' | 'Vendeur' | 'Admin';
  adminRole?: 'SuperAdmin' | 'Moderateur' | 'Commercial';
  accountStatus: string;
  boutiqueId?: string | null;
  photo_profil_url?: string | null;
}

interface AuthContextType {
  user: UserProfile | null;
  supabaseUser: User | null;
  loading: boolean;
  signIn: (email: string, password: string) => Promise<{ success: boolean; error?: string; role?: UserProfile['role'] }>;
  signUp: (email: string, password: string, data: { nom: string; telephone?: string; role: 'Acheteur' | 'Vendeur' }) => Promise<{ success: boolean; error?: string; requiresEmailConfirmation?: boolean }>;
  signOut: () => Promise<void>;
  requestPasswordReset: (email: string) => Promise<{ success: boolean; error?: string }>;
  updatePassword: (password: string) => Promise<{ success: boolean; error?: string }>;
  updateUser: (data: Partial<UserProfile>) => Promise<void>;
  // Legacy methods (mapping to new ones or kept for compatibility during migration)
  login: (email: string, password: string) => Promise<{ success: boolean; error?: string; role?: UserProfile['role'] }>;
  register: (data: { nom: string; email: string; telephone?: string; password: string; isVendeur: boolean }) => Promise<{ success: boolean; error?: string; role?: string; requiresEmailConfirmation?: boolean }>;
  logout: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [supabaseUser, setSupabaseUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  // Function to fetch full profile from public.utilisateurs
  const fetchProfile = async (userId: string): Promise<UserProfile | null> => {
    try {
      const { data, error } = await supabase
        .from('utilisateurs')
        .select('*, vendeurs(boutiques(id)), administrateurs(role)')
        .eq('id', userId)
        .maybeSingle();

      if (error) {
        console.error('Error fetching profile:', error);
        return null;
      }

      if (data) {
        // Extraction sécurisée de l'ID de boutique selon la structure retournée par PostgREST
        const vendeursData = Array.isArray(data.vendeurs) ? data.vendeurs[0] : data.vendeurs;
        const boutiquesArray = vendeursData?.boutiques;
        const boutiqueId = Array.isArray(boutiquesArray) ? boutiquesArray[0]?.id : boutiquesArray?.id;
        const adminData = Array.isArray(data.administrateurs)
          ? data.administrateurs[0]
          : data.administrateurs;

        // Map database response to UserProfile interface
        return {
          id: data.id,
          nom: data.nom,
          email: data.email,
          telephone: data.telephone,
          role: resolveProfileRole(data.type_utilisateur, adminData),
          adminRole: adminData?.role,
          accountStatus: data.statut_compte || 'Actif',
          boutiqueId: boutiqueId || null,
          photo_profil_url: null
        };
      }
      return null;
    } catch (err) {
      console.error('Unexpected error in fetchProfile:', err);
      return null;
    }
  };

  // Restore session and listen for auth changes
  useEffect(() => {
    const initializeAuth = async () => {
      // Get initial session
      const { data: { session } } = await supabase.auth.getSession();

      if (session?.user) {
        setSupabaseUser(session.user);
        const profile = await fetchProfile(session.user.id);
        if (profile?.accountStatus === 'Actif') {
          setUser(profile);
        } else {
          await supabase.auth.signOut();
          setSupabaseUser(null);
          setUser(null);
        }
      } else {
        setUser(null);
      }

      setLoading(false);
    };

    initializeAuth();

    // Listen for changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (session?.user) {
        setSupabaseUser(session.user);
        const profile = await fetchProfile(session.user.id);
        if (profile?.accountStatus === 'Actif') {
          setUser(profile);
        } else {
          setUser(null);
        }
      } else {
        setSupabaseUser(null);
        setUser(null);
      }
      setLoading(true);
      setLoading(false);
    });

    return () => {
      subscription.unsubscribe();
    };
  }, []);

  const signIn = async (email: string, password: string): Promise<{ success: boolean; error?: string; role?: UserProfile['role'] }> => {
    try {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password });
      if (error) return { success: false, error: error.message };
      const profile = await fetchProfile(data.user.id);
      if (!profile) {
        await supabase.auth.signOut();
        return { success: false, error: 'Profil utilisateur introuvable.' };
      }
      if (profile.accountStatus !== 'Actif') {
        await supabase.auth.signOut();
        return { success: false, error: 'Ce compte est suspendu ou désactivé.' };
      }
      setSupabaseUser(data.user);
      setUser(profile);
      return { success: true, role: profile?.role };
    } catch (err: any) {
      return { success: false, error: err.message || 'Une erreur est survenue' };
    }
  };

  const signUp = async (
    email: string, 
    password: string, 
    data: { nom: string; telephone?: string; role: 'Acheteur' | 'Vendeur'; nom_boutique?: string; localisation?: string }
  ): Promise<{ success: boolean; error?: string; requiresEmailConfirmation?: boolean }> => {
    try {
      const { data: authData, error } = await supabase.auth.signUp({
        email,
        password,
        options: {
          data: {
            nom: data.nom,
            telephone: data.telephone,
            role: data.role,
            nom_boutique: data.nom_boutique,
            localisation: data.localisation
          }
        }
      });
      if (error) return { success: false, error: error.message };
      return { success: true, requiresEmailConfirmation: !authData.session };
    } catch (err: any) {
      return { success: false, error: err.message || 'Une erreur est survenue' };
    }
  };

  const signOut = async () => {
    await supabase.auth.signOut();
    setUser(null);
    setSupabaseUser(null);
  };

  const requestPasswordReset = async (email: string) => {
    const { error } = await supabase.auth.resetPasswordForEmail(email, {
      redirectTo: `${window.location.origin}/reset-password`,
    });
    return error ? { success: false, error: error.message } : { success: true };
  };

  const updatePassword = async (password: string) => {
    const { error } = await supabase.auth.updateUser({ password });
    return error ? { success: false, error: error.message } : { success: true };
  };

  // Legacy mappings
  const login = signIn;
  const register = async (data: { nom: string; email: string; telephone?: string; password: string; isVendeur: boolean; nomBoutique?: string; localisation?: string }): Promise<{ success: boolean; error?: string; role?: string; requiresEmailConfirmation?: boolean }> => {
    const result = await signUp(data.email, data.password, {
      nom: data.nom,
      telephone: data.telephone,
      role: data.isVendeur ? 'Vendeur' : 'Acheteur',
      nom_boutique: data.nomBoutique,
      localisation: data.localisation
    });
    return { ...result, role: data.isVendeur ? 'Vendeur' : 'Acheteur' };
  };
  const logout = signOut;

  const updateUser = async (data: Partial<UserProfile>) => {
    if (!user) return;

    const { data: updatedProfile, error } = await supabase.rpc('update_my_profile', {
      profile_name: data.nom ?? user.nom,
      profile_phone: data.telephone ?? user.telephone ?? '',
    });
    if (error) throw error;

    setUser(prev => prev ? {
      ...prev,
      nom: updatedProfile.nom,
      telephone: updatedProfile.telephone || undefined,
    } : null);
  };

  return (
    <AuthContext.Provider value={{ user, supabaseUser, loading, signIn, signUp, signOut, requestPasswordReset, updatePassword, updateUser, login, register, logout }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { supabase } from '../lib/supabase';
